# name: heads_majority_pref
# description: Among pairs with equal switch counts whose H-counts differ, rate of choosing the sequence with more H; the incumbent is H/T symmetric (null near 0.5), so observed above/below null_mean means people favour heads-heavy/tails-heavy sequences as more random.
def test_statistic(df):
    def sw(s):
        return sum(1 for x, y in zip(s, s[1:]) if x != y)
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    swm = {s: sw(s) for s in u}
    ha, hb = df["sequence_a"].str.count("H"), df["sequence_b"].str.count("H")
    m = (df["sequence_a"].map(swm) == df["sequence_b"].map(swm)) & (ha != hb)
    if m.sum() == 0:
        return 0.5
    chose_h = np.where(ha[m] > hb[m], df["chose_left"][m], 1 - df["chose_left"][m])
    return float(np.mean(chose_h))

# name: near_periodic_avoidance
# description: Among pairs with switch-rate difference at most 1/7 where exactly one sequence is near-periodic (period 2-4 with exactly one mismatch, not strictly periodic), rate of choosing the other sequence; observed above null_mean means people penalise almost-repeating patterns that the model's strict periodicity check misses.
def test_statistic(df):
    def alt(s):
        return sum(1 for x, y in zip(s, s[1:]) if x != y) / (len(s) - 1)
    def mism(s, p):
        return sum(1 for i in range(len(s) - p) if s[i] != s[i + p])
    def strict(s):
        n = len(s)
        return any(mism(s, p) == 0 for p in range(1, n // 2 + 1))
    def near(s):
        n = len(s)
        if n < 6 or strict(s):
            return 0
        return int(any(mism(s, p) == 1 for p in range(2, min(4, n // 2) + 1)))
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    am = {s: alt(s) for s in u}
    nm = {s: near(s) for s in u}
    na, nb = df["sequence_a"].map(nm), df["sequence_b"].map(nm)
    d = (df["sequence_a"].map(am) - df["sequence_b"].map(am)).abs()
    m = (na != nb) & (d <= 1.0 / 7 + 1e-9)
    if m.sum() == 0:
        return 0.5
    chose_other = np.where(nb[m] == 1, df["chose_left"][m], 1 - df["chose_left"][m])
    return float(np.mean(chose_other))

# name: shorter_longest_run_pref
# description: Among pairs with equal switch counts but different longest-run lengths, rate of choosing the sequence with the shorter longest run; observed above null_mean means the model under-penalises long streaks beyond what switch rate and periodicity explain.
def test_statistic(df):
    def sw(s):
        return sum(1 for x, y in zip(s, s[1:]) if x != y)
    def lr(s):
        best = cur = 1
        for x, y in zip(s, s[1:]):
            cur = cur + 1 if x == y else 1
            best = max(best, cur)
        return best
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    swm = {s: sw(s) for s in u}
    lrm = {s: lr(s) for s in u}
    sa, sb = df["sequence_a"].map(swm), df["sequence_b"].map(swm)
    la, lb = df["sequence_a"].map(lrm), df["sequence_b"].map(lrm)
    m = (sa == sb) & (la != lb)
    if m.sum() == 0:
        return 0.5
    chose_short = np.where(la[m] < lb[m], df["chose_left"][m], 1 - df["chose_left"][m])
    return float(np.mean(chose_short))

# name: alternation_pref_drift
# description: Rate of choosing the higher-switch-rate sequence in each participant's second half of trials minus their first half (pairs with different rates); the model is stationary (null near 0), so observed below/above null_mean means preference for alternation weakens/strengthens over the session.
def test_statistic(df):
    def alt(s):
        return sum(1 for x, y in zip(s, s[1:]) if x != y) / (len(s) - 1)
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    am = {s: alt(s) for s in u}
    a, b = df["sequence_a"].map(am).values, df["sequence_b"].map(am).values
    c = df["chose_left"].values
    chose_hi = np.where(a > b, c, 1 - c)
    med = df.groupby("participant_id")["trial_index"].transform("median").values
    late = df["trial_index"].values > med
    m = a != b
    r2 = chose_hi[m & late].mean() if (m & late).sum() else 0.5
    r1 = chose_hi[m & ~late].mean() if (m & ~late).sum() else 0.5
    return float(r2 - r1)

# name: alternation_pref_asymmetry
# description: Rate of choosing the higher-switch-rate sequence when both rates are >= 0.5 minus the same rate when both are <= 0.5 (pairs with different rates only); observed below null_mean means people penalise over-alternation less sharply than the quadratic ideal implies, above means more sharply (i.e. the distance-to-ideal shape is wrong).
def test_statistic(df):
    def alt(s):
        return sum(1 for x, y in zip(s, s[1:]) if x != y) / (len(s) - 1)
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    am = {s: alt(s) for s in u}
    a, b = df["sequence_a"].map(am).values, df["sequence_b"].map(am).values
    c = df["chose_left"].values
    chose_hi = np.where(a > b, c, 1 - c)
    diff = a != b
    hi = diff & (a >= 0.5) & (b >= 0.5)
    lo = diff & (a <= 0.5) & (b <= 0.5)
    rh = chose_hi[hi].mean() if hi.sum() else 0.5
    rl = chose_hi[lo].mean() if lo.sum() else 0.5
    return float(rh - rl)

# name: left_rate_matched_pairs
# description: Left-choice rate among pairs whose two sequences have identical switch rate and periodicity status (where the incumbent predicts exactly 0.5); observed above null_mean means people have a left-side response bias the model lacks.
def test_statistic(df):
    def sw(s):
        return sum(1 for x, y in zip(s, s[1:]) if x != y)
    def per(s):
        n = len(s)
        return int(any(all(s[i] == s[i + p] for i in range(n - p)) for p in range(1, n // 2 + 1)))
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    swm = {s: sw(s) for s in u}
    pm_ = {s: per(s) for s in u}
    m = (df["sequence_a"].map(swm) == df["sequence_b"].map(swm)) & (df["sequence_a"].map(pm_) == df["sequence_b"].map(pm_))
    if m.sum() == 0:
        return 0.5
    return float(df["chose_left"][m].mean())
